import com.google.gson.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import org.objectweb.asm.tree.analysis.*;
import net.farmingtales.ftboss.boss.ai.NativeManorDamageBridgeInstaller;
import net.farmingtales.ftboss.boss.ai.NativeManorDeathCancelInstaller;
import net.farmingtales.ftboss.boss.ai.NativeManorMixinPlugin;
public final class ManorDeathCancelComposerV2 {
    private static int checks,links;
    private static final String INSTALLER="net/farmingtales/ftboss/boss/ai/NativeManorDeathCancelInstaller";
    private static final Map<String,ClassNode> hierarchy=new HashMap<>();
    private static void require(boolean value,String label){checks++;if(!value)throw new IllegalStateException(label);}
    private static ClassNode read(byte[] bytes,int flags){ClassNode node=new ClassNode();new ClassReader(bytes).accept(node,flags);return node;}
    private static ClassNode copy(ClassNode node){ClassNode result=new ClassNode();node.accept(result);return result;}
    private static String graph(MethodNode method){return NativeManorDamageBridgeInstaller.graph(method);}
    private static MethodNode method(ClassNode node,String name){return NativeManorDamageBridgeInstaller.method(node,name);}
    private static Map<String,String> graphs(ClassNode node){Map<String,String> values=new LinkedHashMap<>();for(MethodNode method:node.methods)require(values.put(method.name+method.desc,graph(method))==null,"Unique full method signature");return values;}
    private static ClassNode lookup(String name)throws Exception{if(hierarchy.containsKey(name))return hierarchy.get(name);try(InputStream stream=ClassLoader.getSystemResourceAsStream(name+".class")){require(stream!=null,"Linkage class exists "+name);ClassNode node=read(stream.readAllBytes(),ClassReader.SKIP_FRAMES);hierarchy.put(name,node);return node;}}
    private static boolean assignable(String parent,String child,Set<String> seen)throws Exception{if(parent.equals(child))return true;if(!seen.add(child))return false;ClassNode node=lookup(child);if(node.superName!=null&&assignable(parent,node.superName,seen))return true;for(String value:node.interfaces)if(assignable(parent,value,seen))return true;return false;}
    private static ClassWriter writer(){return new ClassWriter(ClassWriter.COMPUTE_FRAMES|ClassWriter.COMPUTE_MAXS){@Override protected String getCommonSuperClass(String first,String second){try{if(first.equals(second))return first;if(first.startsWith("[")||second.startsWith("["))return "java/lang/Object";if(assignable(first,second,new HashSet<>()))return first;if(assignable(second,first,new HashSet<>()))return second;ClassNode node=lookup(first);if((node.access&Opcodes.ACC_INTERFACE)!=0||(lookup(second).access&Opcodes.ACC_INTERFACE)!=0)return "java/lang/Object";while(node.superName!=null){node=lookup(node.superName);if(assignable(node.name,second,new HashSet<>()))return node.name;}return "java/lang/Object";}catch(Exception failure){throw new IllegalStateException(failure);}}};}
    private static byte[] bytes(ClassNode node){ClassWriter writer=writer();node.accept(writer);return writer.toByteArray();}
    private static void verifyMethods(ClassNode node)throws Exception{for(MethodNode method:node.methods)new Analyzer<BasicValue>(new BasicVerifier()).analyze(node.name,method);}
    private static AbstractInsnNode next(AbstractInsnNode node){while(node!=null&&node.getOpcode()<0)node=node.getNext();return node;}
    private static boolean invocation(AbstractInsnNode node,String owner,String name,String desc){return node instanceof MethodInsnNode call&&call.getOpcode()==Opcodes.INVOKESTATIC&&call.owner.equals(owner)&&call.name.equals(name)&&call.desc.equals(desc);}
    private static MethodInsnNode anchor(ClassNode plugin){List<MethodInsnNode> matches=Arrays.stream(method(plugin,"postApply").instructions.toArray()).filter(node->invocation(node,"net/farmingtales/ftboss/boss/ai/NativeBeamComboInstallerV2","verifyInstalled","(Lorg/objectweb/asm/tree/ClassNode;)V")).map(node->(MethodInsnNode)node).toList();require(matches.size()==1,"Unique final original Easter animation verifier after original member fallback");return matches.getFirst();}
    private static void patchPlugin(ClassNode plugin){require(Arrays.stream(method(plugin,"postApply").instructions.toArray()).noneMatch(node->node instanceof MethodInsnNode call&&call.owner.equals(INSTALLER)),"No duplicate lifecycle adapter registration");InsnList added=new InsnList();added.add(new VarInsnNode(Opcodes.ALOAD,2));added.add(new MethodInsnNode(Opcodes.INVOKESTATIC,INSTALLER,"install","(Lorg/objectweb/asm/tree/ClassNode;)I",false));added.add(new InsnNode(Opcodes.POP));added.add(new VarInsnNode(Opcodes.ALOAD,2));added.add(new MethodInsnNode(Opcodes.INVOKESTATIC,INSTALLER,"verifyInstalled","(Lorg/objectweb/asm/tree/ClassNode;)V",false));method(plugin,"postApply").instructions.insert(anchor(plugin),added);}
    private static void unpatchPlugin(ClassNode plugin){AbstractInsnNode first=next(anchor(plugin).getNext());List<AbstractInsnNode> nodes=new ArrayList<>();AbstractInsnNode value=first;for(int index=0;index<5;index++){require(value!=null,"Complete lifecycle plugin adapter");nodes.add(value);value=next(value.getNext());}require(nodes.get(0) instanceof VarInsnNode load&&load.getOpcode()==Opcodes.ALOAD&&load.var==2&&invocation(nodes.get(1),INSTALLER,"install","(Lorg/objectweb/asm/tree/ClassNode;)I")&&nodes.get(2).getOpcode()==Opcodes.POP&&nodes.get(3) instanceof VarInsnNode second&&second.getOpcode()==Opcodes.ALOAD&&second.var==2&&invocation(nodes.get(4),INSTALLER,"verifyInstalled","(Lorg/objectweb/asm/tree/ClassNode;)V"),"Exact five-instruction native lifecycle plugin registration");for(AbstractInsnNode node:nodes)method(plugin,"postApply").instructions.remove(node);}
    public static void main(String[] args)throws Exception{
        Path output=Path.of(args[2]);ClassNode plugin,raw;byte[] oldPlugin;try(ZipFile jar=new ZipFile(args[0])){oldPlugin=jar.getInputStream(jar.getEntry("net/farmingtales/ftboss/boss/ai/NativeManorMixinPlugin.class")).readAllBytes();plugin=read(oldPlugin,0);raw=read(jar.getInputStream(jar.getEntry("net/farmingtales/ftboss/entity/EasterBossEntity.class")).readAllBytes(),ClassReader.SKIP_FRAMES);}
        ClassNode actual=read(Files.readAllBytes(Path.of(args[1])),ClassReader.SKIP_FRAMES);require(Arrays.stream(method(plugin,"postApply").instructions.toArray()).noneMatch(node->node instanceof VarInsnNode load&&load.getOpcode()==Opcodes.ALOAD&&load.var==4),"Existing plugin does not dereference optional MixinInfo in this pure simulation");new NativeManorMixinPlugin().postApply("net.farmingtales.ftboss.entity.EasterBossEntity",raw,"net.farmingtales.ftboss.mixin.NativeManorRaidMixin",null);new NativeManorMixinPlugin().postApply("net.farmingtales.ftboss.entity.EasterBossEntity",raw,"net.farmingtales.ftboss.mixin.NativeAnimationEmitterMixin",null);require(graphs(raw).equals(graphs(actual)),"Full existing plugin pipeline reproduces all 342 actually defined original Boss graphs before new adapter");
        Map<String,String> old=graphs(raw);require(NativeManorDeathCancelInstaller.install(raw)==3,"Three exact committed-death gates installed");NativeManorDeathCancelInstaller.verifyInstalled(raw);require(graphs(NativeManorDeathCancelInstaller.originalView(raw)).equals(old),"Exact full original 342-method reverse proof");Map<String,String> patched=graphs(raw);require(NativeManorDeathCancelInstaller.install(raw)==0&&patched.equals(graphs(raw)),"New native lifecycle adapter is idempotent");long changed=old.entrySet().stream().filter(entry->!entry.getValue().equals(patched.get(entry.getKey()))).count();require(changed==2&&raw.methods.size()==342,"Only two existing method graphs change; 340 others remain exact");verifyMethods(raw);byte[] effective=bytes(raw);ClassNode serialized=read(effective,ClassReader.SKIP_FRAMES);require(graphs(serialized).equals(patched),"Serialized full native composition retains exact graphs");NativeManorDeathCancelInstaller.verifyInstalled(serialized);Files.write(output.resolve("simulated-after.class"),effective);
        Map<String,String> oldPluginGraphs=graphs(plugin);patchPlugin(plugin);verifyMethods(plugin);ClassWriter pluginWriter=new ClassWriter(ClassWriter.COMPUTE_MAXS);plugin.accept(pluginWriter);byte[] pluginBytes=pluginWriter.toByteArray();Files.write(output.resolve("NativeManorMixinPlugin.class"),pluginBytes);ClassNode restored=read(pluginBytes,0);unpatchPlugin(restored);require(graphs(restored).equals(oldPluginGraphs),"Plugin changes only exact native lifecycle registration after original verifiers");int negatives=0;
        for(String fault:List.of("wrong-final-flag","reversed-discard-branch","changed-original-cleanup","duplicate-plugin-registration")){boolean rejected=false;try{if(fault.equals("duplicate-plugin-registration")){ClassNode damaged=read(pluginBytes,0);patchPlugin(damaged);}else{ClassNode damaged=read(effective,ClassReader.SKIP_FRAMES);MethodNode selected=method(damaged,fault.equals("changed-original-cleanup")?"die":"manorHurt");boolean changedFault=false;for(AbstractInsnNode node:selected.instructions){if(!changedFault&&fault.equals("wrong-final-flag")&&node instanceof FieldInsnNode field&&field.name.equals("dead")){field.name="hurtMarked";changedFault=true;}else if(!changedFault&&fault.equals("reversed-discard-branch")&&node instanceof JumpInsnNode branch&&branch.getPrevious() instanceof FieldInsnNode field&&field.name.equals("dead")){branch.setOpcode(Opcodes.IFNE);changedFault=true;}else if(!changedFault&&fault.equals("changed-original-cleanup")&&node instanceof MethodInsnNode call&&call.owner.endsWith("BossBars")&&call.name.equals("untrack")){call.name="track";changedFault=true;}}require(changedFault,"Exact negative-control mutation applied "+fault);NativeManorDeathCancelInstaller.verifyInstalled(damaged);}}catch(IllegalStateException expected){rejected=true;}require(rejected,"Strict adapter rejects "+fault);negatives++;}
        ClassNode living=lookup("net/minecraft/world/entity/LivingEntity");List<FieldNode> fields=living.fields.stream().filter(field->field.name.equals("dead")&&field.desc.equals("Z")).toList();require(fields.size()==1&&(fields.getFirst().access&(Opcodes.ACC_PUBLIC|Opcodes.ACC_PROTECTED))!=0,"Native committed-death flag resolves with lawful subclass access");links++;
        Map<String,Object> receipt=new LinkedHashMap<>();receipt.put("checks",checks);receipt.put("newFieldLinks",links);receipt.put("changedExistingBossMethods",2);receipt.put("unchangedOtherBossMethodGraphs",340);receipt.put("actualOriginalMethodCount",342);receipt.put("nativeFinalDeathGates",3);receipt.put("negativeControls",negatives);receipt.put("asmVerifiedEffectiveBossMethods",342);receipt.put("allOriginalBossGraphsRecoveredExactly",true);receipt.put("allPriorNativeInstallersAndTheirOrderRetained",true);receipt.put("originalDamageAndRebirthAlgorithmsUnchanged",true);receipt.put("noEngineLivingEntityOrThirdPartyClassChanges",true);receipt.put("actualBaselinePluginPipelineReproduced",true);receipt.put("modelOrMusicUploaded",false);Files.writeString(output.resolve("composition-proof.json"),new GsonBuilder().setPrettyPrinting().create().toJson(receipt));System.out.println(new Gson().toJson(receipt));
    }
}
